        if lst[m]<=t: lo=m+1
        else: hi=m
    return lst[lo-1] if lo>0 else None
def find(evs,delta,only_cand=False):
    out=[]
    for u,v,t in evs:
        du=nbr[u]; dv=nbr[v]
        small,large=(du,dv) if len(du)<=len(dv) else (dv,du)
        best=None
        for x in small:
            if x==u or x==v: continue
            if x in large:
                a=last_le(du[x],t); b=last_le(dv[x],t)
                if a is not None and b is not None:
                    lag=t-(a if a>b else b)
                    if best is None or lag<best[0]: best=(lag,x)
